#!/usr/bin/env bash
# Generates type-safe TS bindings for the Aztec L2 contracts in noir-projects/.
# For each contract it copies the compiled artifact into ./artifacts (with a `.d.json.ts` stub so
# tsc types the JSON as NoirCompiledContract instead of inferring the multi-MB literal), runs the
# @aztec/builder `codegen` CLI to emit ./src/<Contract>.ts, and writes ./src/index.ts.
#
# Contracts are listed explicitly below; add a row when a new `type = "contract"` noir package lands.
set -euo pipefail

cd "$(dirname "$0")/.."
ROOT="$(cd ../.. && pwd)"
BUILDER_CLI="$ROOT/yarn-project/node_modules/@aztec/builder/dest/bin/cli.js"

# noir package dir : compiled artifact basename (<package>-<ContractName>.json)
CONTRACTS=(
  "broadcaster_contract:broadcaster_contract-Broadcaster.json"
  "oxide_token_contract:oxide_token_contract-OxideToken.json"
  "passkey_test_account_contract:passkey_test_account_contract-PasskeyTestAccount.json"
)

if [ ! -f "$BUILDER_CLI" ]; then
  echo "aztec-builder not found at $BUILDER_CLI; run \`yarn install\` in yarn-project/ first" >&2
  exit 1
fi

rm -rf artifacts src
mkdir -p artifacts src

# Stub that types every imported artifact JSON as a NoirCompiledContract.
read -r -d '' DECL <<'EOF' || true
import { type NoirCompiledContract } from '@aztec/aztec.js/abi';
const circuit: NoirCompiledContract;
export = circuit;
EOF

for entry in "${CONTRACTS[@]}"; do
  dir="${entry%%:*}"
  basename="${entry##*:}"
  abi="$ROOT/noir-projects/$dir/target/$basename"
  if [ ! -f "$abi" ]; then
    echo "Contract artifact not found: $abi; run noir-projects/bootstrap.sh first" >&2
    exit 1
  fi
  cp "$abi" "artifacts/$basename"
  echo "$DECL" >"artifacts/${basename%.json}.d.json.ts"
done

node --no-warnings "$BUILDER_CLI" codegen --force -o ./src artifacts

# index.ts: header + the list of generated contract names.
INDEX="src/index.ts"
echo "/* Autogenerated file, do not edit! Run \`yarn generate\`. */" >"$INDEX"
echo "" >>"$INDEX"
echo "/** Names of the contracts whose bindings this package exports. */" >>"$INDEX"
echo "export const ContractNames = [" >>"$INDEX"
for ts in src/*.ts; do
  name="$(basename "$ts" .ts)"
  [ "$name" = "index" ] && continue
  echo "  '$name'," >>"$INDEX"
done
echo "];" >>"$INDEX"
